import{_ as a,o as e,c as l,a2 as o}from"./chunks/framework.DXRWYp4X.js";const p=JSON.parse('{"title":"22 · 长矛二：分布式内核（操练册）","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://R2h1.github.io/fullstack-learning-site/22-长矛二-分布式内核"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"22 · 长矛二：分布式内核（操练册） | 全栈 × AI 学习路径"}],["meta",{"property":"og:description","content":"面试级 · 生产级 · 企业级的全栈 + AI 学习课程（个人笔记，内容优先）"}],["meta",{"property":"og:url","content":"https://R2h1.github.io/fullstack-learning-site/22-长矛二-分布式内核"}],["meta",{"name":"twitter:card","content":"summary"}]]},"headers":[],"relativePath":"22-长矛二-分布式内核.md","filePath":"22-长矛二-分布式内核.md","lastUpdated":1793498840000}'),i={name:"22-长矛二-分布式内核.md"};function r(n,t,s,c,d,h){return e(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="_22-·-长矛二-分布式内核-操练册" tabindex="-1">22 · 长矛二：分布式内核（操练册） <a class="header-anchor" href="#_22-·-长矛二-分布式内核-操练册" aria-label="Permalink to &quot;22 · 长矛二：分布式内核（操练册）&quot;">​</a></h1><blockquote><p>达标目标：<strong>造出分布式的三块基石并测对：Raft 共识、LSM 存储引擎、带重试与死信的消息队列。</strong> 一句话理由：12 章教你「用」Redis/MQ/副本集，大厂后端定级的分水岭在于你是否造过它们——Raft 写对的那一刻，CAP、一致性、选主不再是话术，是伤疤。 衔接：11 章（B+ 树与事务——LSM 是它的对位答案）、12 章（缓存/CAP/MQ 的概念层）、13 章（系统设计——本章给它装上引擎盖）。 ⚠️ 操练册：每块引擎以「正确性测试通过」为唯一完成标准，写完没测 = 没写。</p></blockquote><hr><h2 id="_1-为什么选这三块" tabindex="-1">1. 为什么选这三块 <a class="header-anchor" href="#_1-为什么选这三块" aria-label="Permalink to &quot;1. 为什么选这三块&quot;">​</a></h2><ul><li><strong>Raft</strong>：一切高可用中间件的底座（etcd、Kafka KRaft、TiKV 都实现了它）。面试问「副本怎么保证一致性」，能推导 Raft 的人直接结束战斗</li><li><strong>LSM-tree</strong>：写优化存储的另一极（RocksDB 家族），对位 11 章 B+ 树；理解了 compaction，就理解了「写放大/读放大/空间放大」这个工程世界的三角权衡</li><li><strong>MQ</strong>：12 章里最薄的部分（站点 Kafka/RabbitMQ 零覆盖），而它是 AI 工程化的刚需（批处理、背压都靠它，对位 23 章）</li></ul><p>三块共享一个内核：<strong>日志 + 状态机</strong>。造完你会发现 Raft 的 log、LSM 的 WAL、MQ 的 partition log 是同构的——这是本章最值钱的一句话。</p><h2 id="_2-路线-约-14–18-周-与-21-章并行则各半速" tabindex="-1">2. 路线（约 14–18 周，与 21 章并行则各半速） <a class="header-anchor" href="#_2-路线-约-14–18-周-与-21-章并行则各半速" aria-label="Permalink to &quot;2. 路线（约 14–18 周，与 21 章并行则各半速）&quot;">​</a></h2><h3 id="_2-1-raft-第-1–6-周" tabindex="-1">2.1 Raft（第 1–6 周） <a class="header-anchor" href="#_2-1-raft-第-1–6-周" aria-label="Permalink to &quot;2.1 Raft（第 1–6 周）&quot;">​</a></h3><ul><li>交付物：<code>miniraft</code>——单语言打穿（Go/Python/TS 任选）：leader election（随机超时）、log replication、commit、apply；持久化 + 快照先不做，最后补</li><li>测试标准（唯一裁判）： <ol><li>单元测试：election timeout 区间内选主成功、网络分区恢复后旧 leader 退位（term 单调）</li><li>场景测试：杀 leader → 重选耗时上界；脑测分区 → 无 commit 丢失；参照 tests-in-etcd 的思路自搭双集群对比测试</li></ol></li><li>必读：Raft 论文 + Raft 可视化；写之前先把状态图自己画一遍再对照</li><li>坑预告：votedFor 的时机、commitIndex 推进规则「只能提交当前 term 的日志」、preVote（不做会踩选举风暴，作为进阶）</li></ul><p><strong>必会</strong>：白板推导一次选主 + 三条日志复制；讲清「为什么多数派」与节点数/副本数关系。</p><h3 id="_2-2-lsm-存储引擎-第-7–11-周" tabindex="-1">2.2 LSM 存储引擎（第 7–11 周） <a class="header-anchor" href="#_2-2-lsm-存储引擎-第-7–11-周" aria-label="Permalink to &quot;2.2 LSM 存储引擎（第 7–11 周）&quot;">​</a></h3><ul><li>交付物：<code>minilsm</code>——memtable(跳表) → WAL → flush 成 SSTable → leveled compaction → 点查/范围查（Bloom filter + block index 加速）；API 只要 <code>put/get/delete/scan</code></li><li>测试标准：kill -9 后恢复无数据丢失（WAL 回放）；compaction 前后读写结果一致；基准 vs 裸 B 树（11 章 MySQL 的表世界）——写出写放大数字</li><li>与 11 章闭环：用自己的 LSM 和 InnoDB 各跑一次写密集基准，<strong>解释为什么「写多读少」选了不同的树</strong></li></ul><h3 id="_2-3-消息队列-第-12–15-周" tabindex="-1">2.3 消息队列（第 12–15 周） <a class="header-anchor" href="#_2-3-消息队列-第-12–15-周" aria-label="Permalink to &quot;2.3 消息队列（第 12–15 周）&quot;">​</a></h3><ul><li>交付物：<code>minimq</code>——单分区起步：append-only log（复用 2.2 的存储件！）+ producer offset 管理 + consumer pull + at-least-once 语义；再加分区与重平衡；最后补延迟重试队列 + 死信（对齐路线图阶段一的「重试与死信」）</li><li>测试标准：生产者崩溃重发后消费者幂等验证（对位 09 章）；kill broker 恢复后不丢已 ack 消息</li><li>必会：at-most/at-least/exactly-once 的实现代价；ISR vs Raft 多数派——Kafka 与 etcd 治同一种病的两套药，为什么</li></ul><p><strong>本章 D4 终点</strong>：三件全带测试通过 + 每件一篇设计 README（取舍记录，面试直接用）。</p><h2 id="_3-常见误区" tabindex="-1">3. 常见误区 <a class="header-anchor" href="#_3-常见误区" aria-label="Permalink to &quot;3. 常见误区&quot;">​</a></h2><ul><li>❌ 一上来做多语言/分布式部署版 Raft（先单机模拟消息传递，正确性 &gt; 真实性）</li><li>❌ 跳过测试用「看起来能跑」交差（Raft 不测分区行为等于没写）</li><li>❌ LSM 上 Bloom filter 调参花两周（先用朴素实现过基准，再优化）</li><li>❌ MQ 做 exactly-once（工业界靠幂等 + at-least-once，学事务消息概念即可）</li></ul><h2 id="_4-达标标准" tabindex="-1">4. 达标标准 <a class="header-anchor" href="#_4-达标标准" aria-label="Permalink to &quot;4. 达标标准&quot;">​</a></h2><p><strong>L2：</strong></p><ul><li>[ ] 讲清 Raft 选主/复制/安全三规则；画 LSM 读写路径与 compaction 策略</li><li>[ ] 答「Kafka 为什么不选 Raft 用 ISR」并说各自代价</li></ul><p><strong>L3：</strong></p><ul><li>[ ] minimq 在项目一（SaaS 后端）里真接一条业务链路（如异步发通知），带监控</li></ul><p><strong>D4：</strong></p><ul><li>[ ] 三仓库测试绿 + 基准报告 + 设计 README，至少一件被他人 review</li></ul>',24)])])}const u=a(i,[["render",r]]);export{p as __pageData,u as default};
